<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {useRoute} from 'vue-router';import {LayoutDashboard,Landmark,ArrowLeftRight,FlaskConical,ShieldAlert,ChartNoAxesCombined,ClipboardCheck,LogOut,ChevronRight,Activity} from 'lucide-vue-next';import {useAuth} from './stores/auth';
const auth=useAuth();const route=useRoute();const role=ref<'Admin'|'Observer'>('Observer');const password=ref('');const error=ref('');const busy=ref(false);
const links=[{path:'/',title:'Overview',icon:LayoutDashboard},{path:'/loans',title:'Loans',icon:Landmark},{path:'/payments',title:'Payments & webhooks',icon:ArrowLeftRight},{path:'/simulator',title:'Bank simulator',icon:FlaskConical},{path:'/failures',title:'Failures & recovery',icon:ShieldAlert},{path:'/scaling',title:'Scaling & observability',icon:ChartNoAxesCombined},{path:'/reconciliation',title:'Reconciliation',icon:ClipboardCheck}];
const title=computed(()=>links.find(l=>l.path==='/'?route.path==='/':route.path.startsWith(l.path))?.title ?? 'Operations');onMounted(()=>auth.initialize());
async function login(){busy.value=true;error.value='';try{await auth.login(role.value,password.value);password.value=''}catch(e){error.value=e instanceof Error?e.message:'Login failed'}finally{busy.value=false}}
</script>
<template>
  <div v-if="!auth.ready" class="login-shell"><p>Connecting to Month-End LMS…</p></div>
  <div v-else-if="!auth.role" class="login-shell"><div class="login-card"><div class="brand-mark">m.</div><p class="eyebrow">MONTH-END LMS</p><h1>A clear view of<br/>every payment.</h1><p class="muted">Fictional loans. Real processing. Sign in to the operations demo.</p><form @submit.prevent="login"><label>Demo role<el-select v-model="role"><el-option label="Observer" value="Observer"/><el-option label="Admin" value="Admin"/></el-select></label><label>Password<el-input v-model="password" type="password" show-password autocomplete="current-password"/></label><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button type="primary" native-type="submit" :loading="busy" class="login-button">Open dashboard <ChevronRight :size="16"/></el-button></form><small>Local credentials are documented in README.md.</small></div></div>
  <div v-else class="app-shell"><aside class="sidebar"><RouterLink to="/" class="brand"><span class="brand-mark">m.</span><span>Month-End<span class="brand-caption">LOAN OPERATIONS</span></span></RouterLink><div class="workspace-label">WORKSPACE <span>DEMO</span></div><nav aria-label="Main navigation"><RouterLink v-for="link in links" :key="link.path" :to="link.path" :class="{'nav-active':link.path==='/'?route.path==='/':route.path.startsWith(link.path)}"><component :is="link.icon" :size="18"/><span>{{link.title}}</span></RouterLink></nav><div class="sidebar-bottom"><div class="sandbox"><Activity :size="18"/><div>Simulation environment<small>Fictional customers · THB only</small></div></div><button class="user" @click="auth.logout"><span class="avatar">{{auth.role[0]}}</span><span>{{auth.role}}<small>Local demo session</small></span><LogOut :size="16"/></button></div></aside>
    <div class="main-shell"><header class="topbar"><div>Workspace <ChevronRight :size="14"/> <strong>{{title}}</strong></div><div class="topbar-right"><span class="badge good"><span class="status-dot"/>DEMO BUSINESS DATE</span><strong>31 Oct 2026</strong><span class="avatar">{{auth.role[0]}}</span></div></header><main><RouterView/></main><footer>MONTH-END LMS <span>Simulated money · Monthly reducing-balance product · Asia/Bangkok</span></footer></div>
  </div>
</template>
